  // Step 1: Set up data structures
  const queue = [[beginWord]];
  const visited = new Set([beginWord]);
  const wordSet = new Set(wordList);

  // Step 2: BFS loop
  while (queue.length > 0) {
    // Step 3: Process current sequence
    const sequence = queue.shift();
    const currentWord = sequence[sequence.length - 1];

    // Step 4: Generate neighbor words
    for (let i = 0; i < currentWord.length; i++) {
      for (let c = 97; c <= 122; c++) {
        const newWord = currentWord.slice(0, i) + String.fromCharCode(c) + currentWord.slice(i + 1);

        // Step 5: Check and process valid neighbors
        if (wordSet.has(newWord) && !visited.has(newWord)) {
          if (newWord === endWord) {
            return sequence.length + 1;
          }
          visited.add(newWord);
          queue.push([...sequence, newWord]);
        }
      }
    }
